Translate("deDE", "ironforge", {
	title = "Ironforge",
	aliases = { "Stadt Ironforge" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ironforge ist die {link:capital-city}Hauptstadt{/link} des {link:kingdom-of-ironforge}Königreichs Ironforge{/link} und die älteste Stadt der {link:dwarves}Zwerge{/link}. Sie ist in das Herz eines Berges in {link:dun-morogh}Dun Morogh{/link} gehauen, und selbst die {link:horde}Horde{/link} auf dem Gipfel ihrer Macht vermochte sie nicht einzunehmen. In ihrer Mitte brennen die Feuer der {link:the-great-forge}Great Forge{/link} Tag und Nacht, und die Ströme geschmolzenen Metalls, die sie speisen, tauchen die ganze Stadt in Rot und Gold. Um die Schmiede herum liegen die Hallen des Handels, der Gelehrsamkeit, der Magie und des Krieges, und unter dem Thron liegen noch ältere Hallen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die {link:dwarves}Zwerge{/link} glauben, dass Ironforge ihre erste Heimat ist und dass ihr Volk in längst vergangenen Zeitaltern aus dem Stein dieser Berge geformt wurde. Keine Chronik verzeichnet das Jahr, in dem ihre ersten Hallen gehauen wurden. Lange Zeitalter hindurch wurden alle Zwerge von Ironforge aus von einem einzigen Hochkönig regiert. Als er starb, kämpften die Klans Bronzebeard, Wildhammer und Dunkeleisen um seinen Thron. Die Bronzebeards hielten die Stadt, und als die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} zurückkehrten, um sie einzunehmen, wurden sie vor ihren Toren zerschlagen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[König {link:magni-bronzebeard}Magni Bronzebeard{/link} herrscht vom {link:high-seat}High Seat{/link} aus, mit dem Senat von Ironforge an seiner Seite, der nicht immer seiner Meinung ist. Ein großer Teil seines Heeres ist fern und dient der {link:alliance}Allianz{/link}. Sein Bruder {link:muradin-bronzebeard}Muradin Bronzebeard{/link} ging im Norden verloren, und sein Bruder {link:brann-bronzebeard}Brann Bronzebeard{/link} durchstreift die Welt. Seine Tochter Moira ist fort, und er glaubt, dass der Kaiser der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} sie entführt hat. Die {link:gnomes}Gnome{/link} von {link:gnomeregan}Gnomeregan{/link} leben in {link:tinker-town}Tinker Town{/link}, seit ihre Stadt fiel, und ihre Tüftler erfüllen die Hallen mit Lärm. Nun sind die alten versiegelten Wege unter dem High Seat geöffnet worden. Etwas hat die Gräber der Thane gestört, und man hat Dunkeleisenzwerge dabei entdeckt, wie sie sich zu ihnen vorgruben.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:dwarves}Zwerge{/link} der Bronzebeard.{/b} Schmiede, Händler, Soldaten, Priester und Gelehrte bevölkern die Viertel der Stadt.
• {b}Die {link:gnomeregan-exiles}Gnomeregangnome{/link}.{/b} Hochtüftler {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} führt sein Volk von {link:tinker-town}Tinker Town{/link} aus.
• {b}Die Forscherliga.{/b} Von der {link:hall-of-explorers}Hall of Explorers{/link} aus entsendet die {link:explorers-league}Forscherliga{/link} ihre Mitglieder in Ruinen auf der ganzen Welt.
• {b}Reisende der {link:alliance}Allianz{/link}.{/b} {link:humans}Menschen{/link} kommen und gehen mit der gnomischen Bahn aus {link:stormwind-city}Stormwind{/link}.
• {b}Diebe im Dunkeln.{/b} In der Forlorn Cavern schmiedet eine Gesellschaft namens Hidden Circle Pläne, sich einen Anteil an den Reichtümern des Königs zu sichern.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Drei Hämmer.{/b} Die Bronzebeards hielten Ironforge gegen ihre eigene Sippe. Eine Vertragstafel in den königlichen Gewölben bezeugt den Frieden, der folgte: unterzeichnet von den Bronzebeards und den Wildhammers, doch nie von den Dunkeleisenzwergen.
• {b}Der Zweite Krieg.{/b} Die {link:horde}Horde{/link} überrannte Khaz Modan, doch Ironforge hielt stand. Die {link:dwarves}Zwerge{/link} schlossen sich der {link:alliance}Allianz von Lordaeron{/link} an und kämpften, bis die Horde zerschlagen war.
• {b}Der Dritte Krieg.{/b} {link:muradin-bronzebeard}Muradin{/link} zog nach Nordend und kehrte nicht zurück. Die Zwerge zählen ihn zu den Toten.
• {b}Der Fall von {link:gnomeregan}Gnomeregan{/link}.{/b} Als die {link:gnomes}Gnome{/link} ihre Stadt verloren, öffnete {link:magni-bronzebeard}Magni{/link} ihnen Ironforge.
• {b}Die Gegenwart.{/b} Die Hallen unter dem {link:high-seat}High Seat{/link} stehen wieder offen, und das Königreich erfährt, dass sein ältester Feind sich zu seinen ältesten Toten vorgegraben hat.]=],
		},
		{
			title = "Überlieferungen des Berges",
			text = [=[• Ein Steinmetz aus Ironforge schuf ein Denkmal für Sully Balloo, einen Soldaten, der fern der Heimat starb, aus feinem Stein, der aus dem zerstörten {link:lordaeron}Lordaeron{/link} gebracht wurde. Der König bezahlte es selbst.
• Die Bergsteiger, die im Schnee von {link:dun-morogh}Dun Morogh{/link} sterben, kehren als Gewehre heim, ihre Namen in die Schäfte geschnitzt.]=],
		},
	},
})

Translate("deDE", "the-great-forge", {
	title = "The Great Forge",
	aliases = { "Great Forge" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Great Forge füllt die zentrale Halle von {link:ironforge}Ironforge{/link}. Geschmolzenes Metall ergießt sich aus der Höhe in große Becken, und um sie herum arbeiten die Schmiede der Stadt an Ambossen, die niemals erkalten. Die Hitze und das Licht der Schmiede erreichen jedes Viertel, und ihr Hämmern ist der Klang, den die {link:dwarves}Zwerge{/link} Heimat nennen. Händler, Lehrer und Boten drängen sich in ihrem Rund, und die Greifen der Stadt kommen und gehen von der nahen Terrasse. Kein anderer Ort der Stadt ist so geschäftig, und keiner ist so geliebt.]=],
		},
	},
})

Translate("deDE", "the-commons", {
	title = "The Commons",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[The Commons ist das Viertel des Handels in {link:ironforge}Ironforge{/link}. Hier stehen der Vault of Ironforge, wo der Reichtum der Stadt und ihrer Besucher unter Bewachung verwahrt wird, das große Auktionshaus und das Gasthaus von Gastwirt Firebrew. Händler aller Völker der {link:alliance}Allianz{/link} kommen hierher, und das Viertel hallt vom Feilschen wider, von der ersten Stunde bis zur letzten. Reisende, die lange unterwegs waren, kommen ins Gasthaus, um sich an einem warmen Herd und einem starken Bier zu erfreuen, bevor sie weiterziehen.]=],
		},
	},
})

Translate("deDE", "hall-of-explorers", {
	title = "Hall of Explorers",
	aliases = { "Versammlung der Forscher" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Hall of Explorers ist die Heimat der {link:explorers-league}Forscherliga{/link}. Ihre Galerien bergen Relikte, die aus Ruinen auf der ganzen Welt zurückgebracht wurden, ihre Bibliothek bewahrt die Bücher und Karten der Liga, und ihre Gelehrten streiten über die wahren Ursprünge des Zwergenvolkes. {link:high-explorer-magellas}Oberforscher Magellas{/link} hat hier den Vorsitz. {link:advisor-belgrum}Berater Belgrum{/link}, {link:historian-karnik}Historiker Karnik{/link} und {link:prospector-stormpike}Prospektor Stormpike{/link} gehen in der Halle ihren Geschäften nach, und Nachrichten von den Grabungsstätten im {link:badlands}Ödland{/link} und in {link:loch-modan}Loch Modan{/link} treffen zuerst hier ein.]=],
		},
	},
})

Translate("deDE", "tinker-town", {
	title = "Tinker Town",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tinker Town ist das Viertel, das {link:magni-bronzebeard}König Magni{/link} den Gnomen nach dem Fall von {link:gnomeregan}Gnomeregan{/link} überließ. Es klappert von Zahnrädern und zischt vor Dampf, und seine Werkstätten sind vollgestopft mit halbfertigen Apparaten. {link:gelbin-mekkatorque}Hochtüftler Mekkatorque{/link} hält hier im Exil Hof. Von Tinker Town aus fährt die Tiefenbahn tief unter der Erde nach {link:stormwind-city}Stormwind{/link}, und die Tüftler von Gnomeregan schicken Freiwillige zurück in ihre verlorene Stadt, um zu retten, was sie können.]=],
		},
	},
})

Translate("deDE", "the-mystic-ward", {
	title = "The Mystic Ward",
	aliases = { "Mystic Ward" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Mystic Ward ist das Viertel der Stadt, das dem Glauben und der Magie gewidmet ist. Priester des {link:holy-light}Heiligen Lichts{/link} dienen in der Hall of Mysteries, und Magier studieren in den Hallen um sie herum. Es ist ein ruhigerer Ort als der Rest von {link:ironforge}Ironforge{/link}, fern vom Tosen der Schmiede, und wer die höheren Künste sucht, findet hier seine Lehrer.]=],
		},
	},
})

Translate("deDE", "the-military-ward", {
	title = "The Military Ward",
	aliases = { "Military Ward" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Military Ward ist die Festung in der Festung. In ihrer Hall of Arms werden die Krieger von {link:ironforge}Ironforge{/link} unter Muren {link:stormpike-guard}Stormpike{/link} ausgebildet, der lehrt, dass ein Krieger einem Feind niemals den Rücken zukehrt. Die Soldaten des Königs üben hier, bevor sie an die Fronten der {link:alliance}Allianz{/link} marschieren. Es ist ein harter Ort, und die {link:dwarves}Zwerge{/link}, die hier dienen, sind stolz darauf.]=],
		},
	},
})

Translate("deDE", "high-seat", {
	title = "High Seat",
	aliases = { "der High Seat" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der High Seat ist der Thronsaal von {link:ironforge}Ironforge{/link}, erhöht über den westlichen Hallen der Stadt. Hier hält {link:magni-bronzebeard}König Magni Bronzebeard{/link} Hof, bewacht von der Eisernen Königsgarde. Senatoren von Ironforge kommen und gehen in den Geschäften des Reiches, und die Königliche Historikerin hält die Erinnerung des Königreichs nahe am Thron. Eine Tür an der Seite der Halle, lange versiegelt, steht nun offen. Dahinter führt ein Pfad hinab nach {link:old-ironforge}Old Ironforge{/link}.]=],
		},
	},
})

Translate("deDE", "old-ironforge", {
	title = "Old Ironforge",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Old Ironforge liegt unter dem {link:high-seat}High Seat{/link} und ist der älteste Teil der Stadt. Generationen lang waren seine Tore verschlossen, und nur wenige lebende {link:dwarves}Zwerge{/link} hatten es betreten. Nun steht der Weg offen. Ein langer Pfad windet sich durch alte Hallen hinab zu den Höhlen darunter, wo die {link:hall-of-thanes}Hall of Thanes{/link} die Gräber der großen Zwerge der Vergangenheit birgt. Die Hüter dieser Gräber haben seltsame Geräusche aus den Gewölben gehört, und die Toten darin haben begonnen, sich zu regen.]=],
		},
	},
})

Translate("deDE", "magni-bronzebeard", {
	title = "Magni Bronzebeard",
	subtitle = "König von Ironforge",
	found = "Der High Seat, Ironforge",
	hint = "Ersucht im High Seat um eine Audienz beim König.",
	allegiance = "Königreich Ironforge · Allianz",
	aliases = { "Magni", "König Magni", "König Magni Bronzebeard" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Magni Bronzebeard ist König von {link:ironforge}Ironforge{/link} und Herr der {link:dwarves}Zwerge{/link} der Bronzebeard. Er ist der älteste von drei Brüdern, und die schwerste Krone in Khaz Modan ruht auf seinem Haupt. Vom {link:high-seat}High Seat{/link} aus herrscht er über ein stolzes und starrköpfiges Volk, verhandelt mit einem Senat, der nicht immer seine Ansichten teilt, und hält einer {link:alliance}Allianz{/link} die Treue, die ihn teuer zu stehen gekommen ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Magni ist einer der Pfeiler der {link:alliance}Allianz{/link}. Als die {link:horde}Horde{/link} im {link:second-war}Zweiten Krieg{/link} Khaz Modan überrannte, vergaß sein Volk nicht, wer an seiner Seite stand, und {link:ironforge}Ironforge{/link} hat seither sein Wort gegenüber den {link:humans}Menschen{/link} gehalten. Als die {link:gnomes}Gnome{/link} ihre Stadt verloren, nahm er sie auf. Wenn die Allianz ruft, ziehen seine Soldaten aus. Es ist Magnis Bürde, dass jede dieser Entscheidungen von seinem eigenen Volk bezahlt wurde.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führt das {link:kingdom-of-ironforge}Königreich Ironforge{/link} und hält dessen Sitz in der {link:alliance}Allianz{/link}.
• Er schickt sein Heer in die Ferne, um an der Seite der Allianz zu kämpfen, obwohl seine eigenen Lande dadurch dünn bewacht bleiben.
• Er gab den Verbannten von {link:gnomeregan}Gnomeregan{/link} eine Heimat in seiner Stadt.
• Er betrauert seinen Bruder {link:muradin-bronzebeard}Muradin{/link}, der in Nordend verloren ging. Sein Bruder {link:brann-bronzebeard}Brann{/link} ist fern in den Geschäften der Liga unterwegs.
• Er sucht seine Tochter Moira, die in der Brennenden Steppe verschwand, und gibt dem Kaiser der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} die Schuld.]=],
		},
	},
	chapters = {
		{
			title = "Die Ehrung eines Königs",
			hint = [=[Erfüllt den Wunsch des Königs für die Witwe eines gefallenen Soldaten.]=],
			text = [=[Als die Witwe von Sully Balloo ihm schrieb, tat Magni nicht so, als sei der Tod ihres Mannes etwas anderes als ein Verlust gewesen. Er sagte, dass jeder {link:dwarves}Zwerg{/link}, der für die {link:alliance}Allianz{/link} fällt, auf seiner Seele laste. Er konnte Sully nicht zurückbringen, und so ließ er den Großsteinmetz ein Denkmal aus Granit aus {link:lordaeron}Lordaeron{/link} für ihn meißeln, in der Hoffnung, dass die Nachkommenden sich daran erinnern würden, für wen solche Soldaten starben.]=],
		},
		{
			title = "Der Vertrag der Verständigung",
			hint = [=[Birgt einen uralten Vertrag aus den Gewölben unter der Stadt.]=],
			text = [=[Aus dem Reliquary of Kings unter {link:ironforge}Ironforge{/link} kam eine Tafel aus Stein. Magni erkannte sie sofort. Es war der Frieden, der nach dem Krieg der drei Klans geschlossen wurde, in den Tagen seines Vorfahren Madoran, des ersten Bronzebeard, der über Ironforge herrschte. Die Bronzebeards hatten ihn unterzeichnet, und die Wildhammers hatten ihn unterzeichnet. Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} nicht.]=],
		},
		{
			title = "Unter unseren Füßen",
			hint = [=[Macht dem Vorstoß der Dunkeleisenzwerge unter Ironforge ein Ende.]=],
			text = [=[Die Nachricht, dass unter der Stadt eine Streitmacht der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} entdeckt worden war, überraschte den König. Er war froh zu hören, dass ihr Befehlshaber tot war, und befahl sogleich, die Durchbrüche zu versiegeln und die unteren Hallen zu verstärken. Er sandte außerdem einem alten Freund aus dem Klan Wildhammer, {link:earthseer-farsen}Erdseher Farsen{/link}, seine herzlichen Grüße und die Aufforderung, ihn endlich einmal richtig zu besuchen.]=],
		},
		{
			title = "Die verlorene Prinzessin",
			hint = "Erfahrt, was aus der Tochter des Königs geworden ist.",
			text = [=[Magni weinte, als er von Moira sprach. Er hatte seine Männer ausgeschickt, um die {link:burning-steppes}Brennende Steppe{/link} abzusuchen, und die einzige Spur, die sie fanden, wies in die Tiefen des {link:blackrock-mountain}Blackrock{/link}. Er hielt sie für die Gefangene des Kaisers der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link}, Dagran {link:ruins-of-thaurissan}Thaurissan{/link}, gebunden durch seine Zauber, und er wollte den Kaiser tot sehen. Als die Wahrheit zu ihm zurückkam, war sie schlimmer, als er befürchtet hatte. Moira trug Thaurissans Kind, und sie ließ ihm ausrichten, dass der Erbe von {link:ironforge}Ironforge{/link} ein Dunkeleisenzwerg sein würde. Magni konnte nur sagen, dass Thaurissan selbst im Tod gesiegt hatte.]=],
		},
	},
	mentions = {
		{ text = "Die Ehrung eines Königs" },
		{ text = "Die Vermittlung des Friedens" },
		{ text = "Kharan Mighthammer" },
		{ text = "Der Überbringer schlechter Nachrichten" },
		{ text = "Das Schicksal des Königreichs" },
	},
	bonds = {
		{ id = "muradin-bronzebeard", name = "Muradin Bronzebeard", note = "sein Bruder, verloren in Nordend" },
		{ id = "brann-bronzebeard", name = "Brann Bronzebeard", note = "sein jüngster Bruder" },
		{ id = "gelbin-mekkatorque", name = "Gelbin Mekkatorque", note = "sein Verbündeter und Gast" },
		{ id = "earthseer-farsen", name = "Erdseher Farsen", note = "ein alter Freund aus dem Klan Wildhammer" },
		{ id = "royal-historian-archesonus", name = "Königliche Historikerin Archesonus", note = "bewahrt die Erinnerung seines Königreichs" },
		{ id = "senator-barin-redstone", name = "Senator Barin Redstone", note = "ein Senator an seinem Hof" },
	},
})

Translate("deDE", "muradin-bronzebeard", {
	title = "Muradin Bronzebeard",
	subtitle = "Bruder des Königs",
	found = "Verschollen in Nordend",
	allegiance = "Königreich Ironforge",
	aliases = { "Muradin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Muradin Bronzebeard ist der Bruder von {link:magni-bronzebeard}König Magni{/link}. Er war einer der mächtigsten Krieger von {link:ironforge}Ironforge{/link}, ein {link:dwarves}Zwerg{/link} von großer Stärke, offener Rede und warmem Herzen. Im {link:third-war}Dritten Krieg{/link} zog er auf den gefrorenen Kontinent Nordend, und er kehrte nicht heim. Ironforge zählt ihn zu seinen Toten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Muradin war dem Haus von {link:lordaeron}Lordaeron{/link} durch mehr als ein Bündnis verbunden. Er war dem jungen Prinzen {link:arthas-menethil}Arthas Menethil{/link} ein Waffenlehrer gewesen, und die beiden waren Freunde. Dieses Band machte Muradin zum Zeugen der ersten Schritte des Prinzen in den Untergang. Es kostete ihn auch das Leben, so glaubt man jedenfalls in {link:ironforge}Ironforge{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er diente der {link:alliance}Allianz{/link} und war an den Höfen der Menschenkönigreiche bekannt.
• Er lehrte den Prinzen von {link:lordaeron}Lordaeron{/link} die Kunst des Schwertes und des Hammers.
• Er führte eine Expedition von Zwergen nach Nordend, auf der Suche nach einer legendären Runenklinge namens Frostgram.
• Er kämpfte an der Seite von {link:arthas-menethil}Arthas{/link} gegen die Untoten in den gefrorenen Ödnissen.]=],
		},
		{
			title = "Die Reise nach Norden",
			text = [=[Muradins Gruppe hatte Nordend lange nach Frostgram abgesucht, bevor sie {link:arthas-menethil}Arthas{/link} trafen, der einem Schreckenslord über das Meer gefolgt war. Die {link:dwarves}Zwerge{/link} und der Prinz vereinten ihre Kräfte gegen die Untoten. Muradin wurde unruhig, als er seinen alten Schüler beobachtete. Arthas hatte seine eigenen Schiffe verbrannt, damit seine Männer nicht heimkehren konnten, und sein Hass auf den Feind war zum Einzigen geworden, wofür er noch zu leben schien.

Endlich fanden sie die Klinge in einer gefrorenen Höhle, in Eis eingeschlossen und bewacht. Muradin las die dort eingemeißelte Warnung und flehte Arthas an, sie liegen zu lassen. Der Prinz wollte nicht. Als Arthas das Schwert befreite, barst das Eis auseinander, und ein Splitter davon streckte Muradin nieder. Arthas nahm Frostgram und zog ohne ihn weiter.]=],
		},
		{
			title = "In Ironforge",
			text = [=[Die {link:dwarves}Zwerge{/link} erinnern sich an Muradin als einen Helden der {link:alliance}Allianz{/link} und den Bruder ihres Königs. Sein Verlust ist eine weitere Last, die {link:magni-bronzebeard}Magni{/link} trägt, neben einem Heer fern der Heimat und einer Tochter, die von den Dunkeleisenzwergen genommen wurde. In den Hallen von {link:ironforge}Ironforge{/link} wird sein Name mit Trauer ausgesprochen, und mit dem sturen Stolz, den die Zwerge für jene bewahren, die fielen, während sie taten, was sie für richtig hielten.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Was nach jenem Tag aus Muradin wurde, ist in {link:ironforge}Ironforge{/link} nicht bekannt. Sein Volk glaubt, dass er im Eis starb. Keine den Zwergen bekannte Chronik berichtet etwas anderes.]=],
		},
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "sein Bruder" },
		{ id = "brann-bronzebeard", name = "Brann Bronzebeard", note = "sein Bruder" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "sein Schüler" },
	},
})

Translate("deDE", "brann-bronzebeard", {
	title = "Brann Bronzebeard",
	subtitle = "Forscher der Forscherliga",
	found = "Auf Reisen fern von Ironforge",
	allegiance = "Königreich Ironforge · Forscherliga",
	aliases = { "Brann" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Brann Bronzebeard ist der jüngste Bruder von {link:magni-bronzebeard}König Magni{/link}. Wo Magni die Krone und {link:muradin-bronzebeard}Muradin{/link} den Hammer ergriff, ergriff Brann die Karte und die Laterne. Er ist der berühmteste Forscher der {link:explorers-league}Forscherliga{/link}, ein {link:dwarves}Zwerg{/link}, der lieber in einer Titanenruine schläft als in einem königlichen Bett.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Brann ist der lebendige Geist der großen Frage der Liga: Woher kamen die {link:dwarves}Zwerge{/link}? Er hat sein Leben damit verbracht, die uralten Orte der Welt nach der Antwort abzusuchen, und sein Name öffnet Türen, die geringeren Forschern verschlossen blieben. Die Gelehrten der Liga in der {link:hall-of-explorers}Hall of Explorers{/link} führen seine Arbeit fort, während er umherzieht.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hat Ruinen in den {link:eastern-kingdoms}Östlichen Königreichen{/link} und darüber hinaus auf der Suche nach den Ursprüngen der {link:dwarves}Zwerge{/link} erforscht.
• Er wird zu den führenden Mitgliedern der {link:explorers-league}Forscherliga{/link} gezählt.]=],
		},
		{
			title = "Die große Frage",
			text = [=[Die Frage, die Brann antreibt, ist dieselbe, die die ganze Liga stellt: Wurden die {link:dwarves}Zwerge{/link} wirklich von den Titanen aus Stein geformt? In seiner Abwesenheit sind seine Kollegen einer Antwort näher gekommen als je zuvor. Aus den Tiefen von {link:uldaman}Uldaman{/link} haben sie Aufzeichnungen über die Werke der Titanen zurückgebracht, und diese Aufzeichnungen weisen auf noch größere Gewölbe in den Wüsten des Südens. Es ist die Art von Entdeckung, der Brann sein Leben gewidmet hat.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Branns Reisen haben ihn weit von {link:ironforge}Ironforge{/link} fortgeführt, und niemand in der Stadt kann sagen, wo er sich jetzt befindet. Von seinen Fahrten hören die Hallen des {link:high-seat}High Seat{/link} nur Gerüchte. Dieser Eintrag verzeichnet nur, was gewiss ist.]=],
		},
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "sein ältester Bruder" },
		{ id = "muradin-bronzebeard", name = "Muradin Bronzebeard", note = "sein Bruder" },
		{ id = "high-explorer-magellas", name = "Oberforscher Magellas", note = "führt die Liga in seiner Abwesenheit" },
	},
})

Translate("deDE", "gelbin-mekkatorque", {
	title = "Gelbin Mekkatorque",
	subtitle = "Hochtüftler, König der Gnome",
	found = "Tinker Town, Ironforge",
	hint = "Sucht den Hochtüftler in Tinker Town auf.",
	allegiance = "Gnomeregangnome · Allianz",
	aliases = { "Mekkatorque", "Hochtüftler Mekkatorque", "Gelbin", "Hochtüftler Gelbin Mekkatorque" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gelbin Mekkatorque ist der Hochtüftler der {link:gnomes}Gnome{/link}, der König eines Volkes, das sein Königreich verloren hat. Er herrschte in {link:gnomeregan}Gnomeregan{/link}, als die Stadt groß war. Heute herrscht er von einer Werkstatt in {link:tinker-town}Tinker Town{/link} aus, ein Gast der {link:dwarves}Zwerge{/link}, während der größte Teil seines Volkes tot, vergiftet oder zerstreut ist. Er hat weder seinen Verstand noch seinen Willen verloren. Er will heimkehren.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Mekkatorque hält die {link:gnomes}Gnome{/link} zusammen. Ohne ihn wären die Verbannten eine Menge von Flüchtlingen. Mit ihm bleiben sie ein Volk, mit einem Sitz unter den Völkern der {link:alliance}Allianz{/link} und einem Anspruch auf ihre Stadt, den sie nie aufgegeben haben.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte die {link:gnomes}Gnome{/link} von {link:gnomeregan}Gnomeregan{/link} als Hochtüftler.
• Als sich die {link:troggs}Troggs{/link} unter der Stadt erhoben, wandte er in einer verzweifelten Säuberung die eigenen Künste der Gnome gegen sie, und die Stadt wurde vergiftet.
• Er führte die Überlebenden nach {link:ironforge}Ironforge{/link} und machte {link:tinker-town}Tinker Town{/link} zu ihrer Heimat.
• Er schickt Freiwillige zurück nach Gnomeregan, um zu bergen, was zurückgelassen wurde, und um den Verräter zu treffen, der die Stadt hält.]=],
		},
		{
			title = "Der Fall der Stadt",
			text = [=[Keine Chronik verzeichnet das Jahr, in dem die {link:troggs}Troggs{/link} aus den Tiefen unter {link:gnomeregan}Gnomeregan{/link} heraufkamen. Sie kamen in großer Zahl, und die Stadt konnte sie nicht zurückhalten. Mekkatorque entschied sich, sie mit einer Waffe aus der eigenen Herstellung der {link:gnomes}Gnome{/link} auszumerzen. Sie tötete Troggs, doch sie tötete auch sehr viele Gnome, und sie ließ die Stadt von Gift durchtränkt zurück. Viele derer, die überlebten, wurden zu kranken und geistlosen Leprösen. Die Übrigen flohen in den Schnee von {link:dun-morogh}Dun Morogh{/link}.]=],
		},
		{
			title = "Der Hof im Exil",
			text = [=[In {link:tinker-town}Tinker Town{/link} hat das Volk des Hochtüftlers nicht aufgehört zu arbeiten. Tüftlermeister Overspark hofft, seinen armen Techbot zu reparieren, dessen Verstand beim Fall verkehrt wurde. Meistermechaniker Castpipe stellt Trupps zusammen, um wichtige Aufzeichnungen aus den Terminals der Stadt zu bergen. Klockmort Spannerspan braucht die Teile, an deren Mitnahme bei der Flucht niemand gedacht hat. Jede solche Mission ist ein kleiner Schritt zurück nach {link:gnomeregan}Gnomeregan{/link}, und Mekkatorque ermutigt sie alle.]=],
		},
	},
	chapters = {
		{
			title = "Der große Verrat",
			hint = "Streckt den Verräter nieder, der über Gnomeregan herrscht.",
			text = [=[Mekkatorque hatte {link:mekgineer-thermaplugg}Sicco Thermaplugg{/link} vertraut. Er hätte sich nie vorgestellt, dass Thermaplugg ihn und das ganze Gnomenvolk verraten würde, und er versteht noch immer nicht, warum, denn Macht und Reichtum wären Thermaplugg mit der Zeit zugefallen. Nun sitzt der Verräter in den Ruinen, ein König über nichts. Als die Nachricht kam, dass Thermaplugg gefallen war, erlaubte sich Mekkatorque einen grimmigen Scherz und wandte seine Gedanken dann dem Tag zu, an dem die {link:gnomes}Gnome{/link} ihre Stadt zurückerobern würden.]=],
		},
	},
	mentions = {
		{ text = "Datenrettung" },
		{ text = "Rettet Techbots Gehirn!" },
		{ text = "Unentbehrliche Künstlichkeiten" },
	},
	bonds = {
		{ id = "mekgineer-thermaplugg", name = "Robogenieur Thermaplugg", note = "der Verräter" },
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "sein Gastgeber und Verbündeter" },
		{ id = "razzle-sprysprocket", name = "Razzle Sprysprocket", note = "einer aus seinem Volk, der ein Heilmittel sucht" },
	},
})

Translate("deDE", "royal-historian-archesonus", {
	title = "Königliche Historikerin Archesonus",
	subtitle = "Königliche Historikerin von Ironforge",
	found = "Der High Seat, neben dem Thron",
	hint = [=[Sprecht mit der Historikerin, die neben dem Thron die Erinnerung des Königreichs bewahrt.]=],
	allegiance = "Königreich Ironforge",
	aliases = { "Archesonus" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Königliche Historikerin Archesonus bewahrt die Erinnerung von {link:ironforge}Ironforge{/link} neben dem Thron von {link:magni-bronzebeard}König Magni{/link}. Jeder, der fragt, kann von ihr die Geschichte des Königreichs hören. Die Erzählung, die sie am ernstesten vorträgt, ist die der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} und der Stadt {link:ruins-of-thaurissan}Thaurissan{/link}, die verbrannte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Archesonus ist die Stimme der Vergangenheit von {link:ironforge}Ironforge{/link}. Die {link:dwarves}Zwerge{/link} sind ein Volk mit langem Gedächtnis, und im {link:high-seat}High Seat{/link} hat dieses Gedächtnis eine Hüterin. Ihr Wissen über die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} ist dringlich geworden, denn der alte Feind des Königreichs ist wieder in Bewegung.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie lehrt die Geschichte von {link:ironforge}Ironforge{/link} all jene, die zum {link:high-seat}High Seat{/link} kommen.
• Sie schickt Sucher zu den Ruinen von {link:ruins-of-thaurissan}Thaurissan{/link} in der Brennenden Steppe, um die dort zurückgelassenen Relikte zu deuten.]=],
		},
	},
	chapters = {
		{
			title = "Die Geschichte von Thaurissan",
			hint = [=[Bittet die Königliche Historikerin um die Geschichte der Dunkeleisenzwerge.]=],
			text = [=[Archesonus beginnt weit in der Vergangenheit, als die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} noch eine eigene Stadt besaßen. {link:ruins-of-thaurissan}Thaurissan{/link} stand in einem grünen Land, das heute die {link:burning-steppes}Brennende Steppe{/link} ist, und in jenen Tagen lagen die Zwergenklans miteinander im Krieg. Dann zerstörte eine schreckliche Explosion die Stadt, und das Land meilenweit ringsum verbrannte zu Asche. Was die Explosion verursachte, kann kein Historiker sagen, wie sie zugibt. Die überlebenden Dunkeleisenzwerge zogen in den Berg und begannen von Neuem. Aus der Asche erhob sich die Blackrockspitze, und {link:the-cauldron}der Kessel{/link} der Sengenden Schlucht wurde befestigt. Bald gab es Gerüchte über ein uraltes Böses, das das Reich der Dunkeleisenzwerge von innen heraus beherrschte. Ihre Erzählung endet in der Gegenwart. Die Dunkeleisenzwerge werden jedes Jahr öfter an der Oberfläche gesehen. Sie haben Festungen im {link:badlands}Ödland{/link} errichtet, große Trupps nach {link:uldaman}Uldaman{/link} geschickt und sogar den Damm von {link:loch-modan}Loch Modan{/link} angegriffen.]=],
		},
		{
			title = "Die schwelenden Ruinen",
			hint = [=[Deutet die Relikte von Thaurissan und bringt ihre Erinnerungen heim.]=],
			text = [=[Die Relikte der zerstörten Stadt bergen Erinnerungen, und wer sie berührt, behält sie. Ein Wesen aus reiner Flamme. Acht {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} bei einem Ritual. Einer von ihnen am Ende allein, kniend zwischen sieben Toten vor einer Feuersäule. Archesonus hörte diese Erinnerungen und sagte, dass sie vieles erklärten und dass es noch viel mehr zu lernen gebe.]=],
		},
	},
	mentions = {
		{
			text = [=[Die schwelenden Ruinen von {link:ruins-of-thaurissan}Thaurissan{/link}]=],
		},
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "ihr König" },
	},
})

Translate("deDE", "high-explorer-magellas", {
	title = "Oberforscher Magellas",
	subtitle = "Oberforscher der Forscherliga",
	found = "Die Hall of Explorers",
	hint = "Sprecht mit dem Oberforscher in der Hall of Explorers.",
	allegiance = "Forscherliga",
	aliases = { "Magellas" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Oberforscher Magellas führt die {link:explorers-league}Forscherliga{/link} von der {link:hall-of-explorers}Hall of Explorers{/link} aus. Er ist ein vielbeschäftigter {link:dwarves}Zwerg{/link} und lässt es seine Besucher wissen. Doch niemand in {link:ironforge}Ironforge{/link} begeistert sich mehr für eine echte Entdeckung, und wenn eine auf seinem Tisch landet, ist es mit seiner Würde vorbei.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Unter Magellas verfolgt die Liga die Frage, die ihr am wichtigsten ist: den Beweis, dass die {link:dwarves}Zwerge{/link} von den Titanen aus Stein geformt wurden, die in den alten Aufzeichnungen die Schöpfer genannt werden. Er glaubt, dass dieser Beweis in Reichweite sein könnte.]=],
		},
		{
			title = "Taten",
			text = [=[• Er leitet die Expeditionen der Liga und belohnt jene, die ihr dienen, aus dem Tresor der Liga.
• Er studiert die Miniaturausgabe der Discs of Norgannon, die aus {link:uldaman}Uldaman{/link} zurückgebracht wurde.
• Er richtet den Blick der Liga auf {link:valley-of-the-watchers}Uldum{/link}, weit im Süden in {link:tanaris}Tanaris{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Die Platinscheiben",
			hint = "Bringt der Liga einen Fund aus den Tiefen von Uldaman.",
			text = [=[Als eine Nachbildung der Discs of Norgannon im Kleinformat vor ihn gelegt wurde, fragte Magellas, wo sie gefunden worden war, und fragte dann noch einmal, und konnte die Antworten nicht glauben. Er nannte es den Fund des Jahrhunderts. Wenn die Scheiben aussagten, was er vermutete, würden sie die alte Frage nach dem Ursprung der {link:dwarves}Zwerge{/link} ein für alle Mal klären.]=],
		},
		{
			title = "Uldum lockt",
			hint = [=[Folgt den Scheiben zu den Toren von Uldum und erstattet Bericht.]=],
			text = [=[Die Scheiben führten zu den versiegelten Toren von {link:valley-of-the-watchers}Uldum{/link}, wo ein weiterer {link:the-night-watch}Wächter{/link} aus Stein von Platten sprach, die fehlten. Magellas stimmte seinen Gelehrten zu, dass die Suche warten müsse, bis sie wüssten, wo sie suchen sollten. Er versprach, dass die Liga, wenn die Zeit gekommen sei, dieselben Hände wieder ins Feld schicken würde.]=],
		},
	},
	mentions = {
		{ text = "Die Platinscheiben" },
		{ text = "Vorzeichen von {link:valley-of-the-watchers}Uldum{/link}" },
	},
	bonds = {
		{ id = "historian-karnik", name = "Historiker Karnik", note = "sein Gelehrter" },
		{ id = "brann-bronzebeard", name = "Brann Bronzebeard", note = "der berühmteste Forscher der Liga" },
	},
})

Translate("deDE", "advisor-belgrum", {
