	subtitle = "Historiker der Forscherliga",
	found = "Die Hall of Explorers",
	hint = [=[Findet den Historiker der Liga, der um seinen Freund Hammertoe trauert.]=],
	allegiance = "Forscherliga",
	aliases = { "Karnik" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Historiker Karnik arbeitete mit dem Forscher Hammertoe daran, die verlorenen Artefakte von {link:uldaman}Uldaman{/link} zu finden, bis die Shadowforge Hammertoe für sein Wissen töteten. Karnik spricht noch immer mit dem Geist seines Freundes. Er studiert außerdem die uralten Orte des Südens und hat Hinweise auf {link:stranglethorn-vale}das Tal{/link} der Behüter in der {link:tanaris}Wüste von Tanaris{/link} gefunden.]=],
