	},
	bonds = {
		{ id = "advisor-belgrum", name = "Berater Belgrum", note = "spricht für den König" },
		{ id = "high-explorer-magellas", name = "Oberforscher Magellas", note = "sein Vorgesetzter" },
	},
})

Translate("deDE", "prospector-stormpike", {
	title = "Prospektor Stormpike",
	subtitle = "Prospektor der Forscherliga",
	found = "Die Hall of Explorers",
	hint = "Findet den jähzornigen Prospektor in der Hall of Explorers.",
	allegiance = "Forscherliga",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Prospektor Stormpike beaufsichtigt die Grabungen der Liga von der {link:hall-of-explorers}Hall of Explorers{/link} aus, und er erträgt belanglose Angelegenheiten nicht gern. Er gerät schnell in Zorn, wenn eine Grabung langsam vorankommt, und noch schneller, wenn Sprengpulver verloren geht. Unter dem Jähzorn liegt Treue: Als {link:troggs}Troggs{/link} {link:uldaman}Uldaman{/link} überrannten, galt sein erster Gedanke seinem Freund {link:the-lost-dwarves}Baelog{/link} und den Zwergen, die hinter den Linien eingeschlossen waren.]=],
