	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Barin Redstone sitzt im Senat von {link:ironforge}Ironforge{/link} und nimmt am Hof des Königs im {link:high-seat}High Seat{/link} teil. Er ist als griesgrämiger Zeitgenosse bekannt. Als ein Bericht aus {link:kharanos}Kharanos{/link} eintraf, der sich für Arbeiten im Feld auf die Autorität des Königs selbst berief, war Redstone empört, über den Verfasser wie über den König, und er warnte, dass der Senat nicht erfreut sein würde.]=],
