	aliases = { "Afadra" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Afadra Dunwall ist eine Hüterin des Wissens von {link:ironforge}Ironforge{/link}, eine der Hüterinnen, die die Gräber der {link:hall-of-thanes}Hall of Thanes{/link} pflegen. Seltsame Geräusche sind aus den Gewölben darunter gedrungen, und die Geister der Toten, die nur leicht schlafen, sind erwacht. Afadra will sie wieder zur Ruhe betten. Sie will auch, dass die anderen Hüter aufhören, ihre Pflichten wegen Geistern zu verweigern.]=],
