Translate("deDE", "thom-filch", {
	title = "Thom Filch",
	subtitle = "Gnom der Gewölbe",
	found = "Old Ironforge, unter dem High Seat",
	hint = [=[Findet den Gnom in Old Ironforge, der dort patrouillierte, wo er nicht hätte sein sollen.]=],
	allegiance = "Unbekannt",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Thom Filch ist ein {link:gnomes}Gnom{/link}, der nach eigenen Worten gerade die Gewölbe unter {link:ironforge}Ironforge{/link} bestreifte, als die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} in Maulwurfmaschinen aus dem Fels hervorbrachen. Er will, dass die unbezahlbaren Relikte der Gewölbe geborgen werden. Er nennt sie Beute, dann kulturelle Erbstücke, und verspricht, dass jedes einzelne verzeichnet und an seinen Platz zurückgebracht wird. Nur wenige, die ihn hören, glauben es.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Thom Filch sah als Erster, wie die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} in die Gewölbe heraufkamen, was auch immer er zu jener Zeit dort tat.]=],
		},
	},
	mentions = {
